def _type(type_name):
    if type_name == "Integer()": return sa.Integer()
    if type_name == "Text()": return sa.Text()
    if type_name == "LargeBinary()": return sa.LargeBinary()
    if type_name == "JSON()": return sa.JSON()
    if type_name == "Float()": return sa.Float()
    if type_name == "Boolean()": return sa.Boolean()
    if type_name == "VECTOR(dim=384)": return Vector(384)
    if type_name == "DateTime(timezone=True)": return sa.DateTime(timezone=True)
    if type_name == "DateTime()": return sa.DateTime()
    if type_name.startswith("String(length="):
        return sa.String(length=int(type_name[len("String(length="):-1]))
    if type_name == "String()": return sa.String()
    raise ValueError(f"Unsupported baseline type: {type_name}")

def _server_default(value):
    if value is None: return None
    if value == "True": return sa.text("true")
    if value == "False": return sa.text("false")
    if value.lstrip("-").replace(".", "", 1).isdigit(): return sa.text(value)
    return sa.text("'" + value.replace("'", "''") + "'")

def _foreign_key(spec):
    target = spec["target"]
    return sa.ForeignKey(target, ondelete=spec["ondelete"]) if spec["ondelete"] else sa.ForeignKey(target)

def _constraint_name(table_name, columns):
    raw = "uq_" + table_name + "_" + "_".join(columns)
    if len(raw) <= 63:
        return raw
    digest = hashlib.sha1(raw.encode("utf-8")).hexdigest()[:8]
    return raw[:54] + "_" + digest

def upgrade():
    # pgvector is a prerequisite for all vector columns in this baseline.
    # The database role must have permission to install extensions.
    op.execute("CREATE EXTENSION IF NOT EXISTS vector")
    for table in _TABLES:
        columns = []
        foreign_keys = {fk["local"]: fk for fks in table["fks"] for fk in fks}
        for column in table["columns"]:
            kwargs = {"nullable": column["nullable"], "primary_key": column["pk"]}
            default = _server_default(column["default"])
            if default is not None: kwargs["server_default"] = default
            args = [column["name"], _type(column["type"])]
            if column["name"] in foreign_keys: args.append(_foreign_key(foreign_keys[column["name"]]))
            columns.append(sa.Column(*args, **kwargs))
        for unique_columns in table["unique_constraints"]:
            name = _constraint_name(table["name"], unique_columns)
            columns.append(sa.UniqueConstraint(*unique_columns, name=name))
        op.create_table(table["name"], *columns)
    for table in _TABLES:
        for index in table["indexes"]:
            op.create_index(index["name"], table["name"], index["columns"], unique=index["unique"])
    # Retain the case-insensitive email uniqueness guaranteed by the legacy path.
    op.create_index("ix_users_email_lower", "users", [sa.text("lower(email)")], unique=True)

def downgrade():
    raise NotImplementedError("The baseline schema is irreversible; restore a database backup to roll back.")
